-- 도커 세트 228. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order 는 통합 시 별도로 정한다. 원본: 02_quest_set.sql, 03_quest_set228.sql. docs/specs/spec_docker_volume_network_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 228, '도커 볼륨과 네트워크 실습: 데이터 보존, 바인드 마운트, 읽기 전용, 이름으로 통신', '볼륨을 만들고 컨테이너를 지워도 데이터가 남는지 확인하고, 바인드 마운트와 읽기 전용(:ro) 마운트를 비교합니다. 직접 만든 네트워크에서 컨테이너를 이름으로 부르고, 쓰는 중인 볼륨이 삭제되지 않는 이유를 찾아 정리하는 연습입니다.', 'docker', '도커'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 228);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 1, '볼륨 만들고 목록 보기', '이름이 **`appdata`** 인 볼륨을 만들고, 볼륨 이름 목록(이름만, 한 줄에 하나)을 `/tmp/vols.txt` 에 저장하세요.', '볼륨은 `docker volume` 아래 명령으로 다룹니다. 만들기는 `create`, 목록은 `ls` 이고, `-q` 를 붙이면 이름만 나와요.', 'docker volume create appdata
docker volume ls -q > /tmp/vols.txt
cat /tmp/vols.txt

# 볼륨은 컨테이너와 따로 만들어 두는 저장 공간이다. ls -q 는 이름만 보여 준다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; true"]', '["sh", "-c", "( docker volume inspect appdata >/dev/null 2>&1 ) && ( grep -qx appdata /tmp/vols.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "appdata 볼륨이 있다", "cmd": ["sh", "-c", "docker volume inspect appdata >/dev/null 2>&1"]}, {"label": "목록 파일에 appdata 가 있다", "cmd": ["sh", "-c", "grep -qx appdata /tmp/vols.txt"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 2, '볼륨이 놓인 위치 찾기', '볼륨 `appdata` 가 이 머신의 **어느 경로**에 실제로 저장되는지(`Mountpoint`) 그 경로만 `/tmp/mp.txt` 에 저장하세요. 볼륨은 이미 만들어 두었습니다.', '`docker volume inspect appdata` 는 JSON 으로 알려 줘요. 컨테이너의 `inspect -f` 처럼 `-f ''{{.항목}}''` 로 한 값만 뽑을 수 있습니다.', 'docker volume inspect appdata
docker volume inspect -f ''{{.Mountpoint}}'' appdata > /tmp/mp.txt
cat /tmp/mp.txt

# 볼륨의 실제 데이터는 Docker 가 관리하는 디렉터리(.../volumes/이름/_data)에 있다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker volume create appdata >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q \\"/appdata/_data$\\" /tmp/mp.txt ) && ( [ \\"$(cat /tmp/mp.txt)\\" = \\"$(docker volume inspect -f ''{{.Mountpoint}}'' appdata)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "경로가 appdata/_data 로 끝난다", "cmd": ["sh", "-c", "grep -q \\"/appdata/_data$\\" /tmp/mp.txt"]}, {"label": "실제 Mountpoint 와 같다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/mp.txt)\\" = \\"$(docker volume inspect -f ''{{.Mountpoint}}'' appdata)\\" ]"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 3, '컨테이너를 지워도 남는 데이터', '볼륨 `notes` 는 이미 있습니다. 컨테이너 하나로 볼륨 안 `memo.txt` 에 `saved` 를 쓰고 그 컨테이너를 **지운 뒤**, **새 컨테이너**로 같은 볼륨의 `memo.txt` 를 읽어 `/tmp/memo.txt` 에 저장하세요. 컨테이너는 남기지 않습니다.', '볼륨은 `-v 볼륨이름:컨테이너경로` 로 붙여요. `--rm` 을 쓰면 끝나자마자 컨테이너가 지워집니다. 같은 `-v notes:/data` 를 두 번 쓰면 돼요.', 'docker run --rm -v notes:/data alpine sh -c ''echo saved > /data/memo.txt''
docker run --rm -v notes:/data alpine cat /data/memo.txt > /tmp/memo.txt
cat /tmp/memo.txt

# 컨테이너는 사라져도 볼륨의 데이터는 남는다. 같은 볼륨을 다시 붙이면 이어서 쓸 수 있다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker volume create notes >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(docker run --rm -v notes:/data alpine cat /data/memo.txt)\\" = saved ] ) && ( [ \\"$(cat /tmp/memo.txt)\\" = saved ] ) && ( [ -z \\"$(docker ps -aq)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "볼륨 안에 saved 가 있다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v notes:/data alpine cat /data/memo.txt)\\" = saved ]"]}, {"label": "/tmp/memo.txt 가 saved 이다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/memo.txt)\\" = saved ]"]}, {"label": "남은 컨테이너가 없다", "cmd": ["sh", "-c", "[ -z \\"$(docker ps -aq)\\" ]"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 4, '호스트 폴더를 붙이기 (바인드 마운트)', '폴더 `/tmp/site` 에는 `index.txt` 가 있습니다. 이 폴더를 컨테이너의 `/site` 에 붙여 컨테이너 안에서 `made.txt` 를 만들고, 내용을 `from-container` 로 하세요. 끝나면 컨테이너 밖 `/tmp/site/made.txt` 에서 보여야 합니다.', '`-v` 의 앞쪽에 볼륨 이름 대신 **`/`로 시작하는 경로**를 쓰면 그 폴더가 그대로 붙어요. 컨테이너는 `--rm` 으로 쓰고 지우면 편합니다.', 'docker run --rm -v /tmp/site:/site alpine sh -c ''echo from-container > /site/made.txt''
ls /tmp/site
cat /tmp/site/made.txt

# 바인드 마운트는 머신의 폴더를 그대로 붙인다. 안에서 만든 파일이 밖에서 바로 보인다 (볼륨은 Docker 가 위치를 관리)', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; mkdir -p /tmp/site; echo hello > /tmp/site/index.txt; true"]', '["sh", "-c", "( [ \\"$(cat /tmp/site/made.txt)\\" = from-container ] ) && ( [ \\"$(cat /tmp/site/index.txt)\\" = hello ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "made.txt 내용이 맞다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/site/made.txt)\\" = from-container ]"]}, {"label": "원래 index.txt 가 그대로다", "cmd": ["sh", "-c", "[ \\"$(cat /tmp/site/index.txt)\\" = hello ]"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 5, '읽기 전용으로 붙이면 쓰기가 막힌다', '볼륨 `config` 의 `app.conf` 에는 `v1` 이 들어 있습니다. 이 볼륨을 **읽기 전용**으로 붙인 컨테이너에서 `app.conf` 를 `v2` 로 덮어써 보세요. 오류 메시지(표준 오류)를 `/tmp/ro.txt` 에 저장하고, 볼륨의 값은 `v1` 그대로여야 합니다.', '`-v 볼륨:경로:ro` 처럼 끝에 `:ro` 를 붙여요. 오류는 `2> /tmp/ro.txt` 로 파일에 받을 수 있습니다.', 'docker run --rm -v config:/cfg:ro alpine sh -c ''echo v2 > /cfg/app.conf'' 2> /tmp/ro.txt
cat /tmp/ro.txt

# :ro 는 컨테이너가 그 경로에 쓰지 못하게 한다. 설정·참고 자료를 보여 주기만 할 때 쓴다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker volume create config >/dev/null 2>&1; docker run --rm -v config:/cfg alpine sh -c ''echo v1 > /cfg/app.conf'' >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -qi \\"read-only\\" /tmp/ro.txt ) && ( [ \\"$(docker run --rm -v config:/cfg alpine cat /cfg/app.conf)\\" = v1 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류에 Read-only 가 있다", "cmd": ["sh", "-c", "grep -qi \\"read-only\\" /tmp/ro.txt"]}, {"label": "볼륨의 값은 v1 그대로다", "cmd": ["sh", "-c", "[ \\"$(docker run --rm -v config:/cfg alpine cat /cfg/app.conf)\\" = v1 ]"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 6, '네트워크 만들기', '이름이 `appnet` 인 **새 네트워크를 만드는** 명령입니다. 빈칸을 채우세요.', '다루는 대상(네트워크/볼륨) 다음에 동작(만들기)이 와요.', NULL, NULL, '[]', 'fill', '["network", "volume", "create", "ls", "inspect", "rm"]', NULL, '`docker network create 이름` 은 사용자 정의 브리지 네트워크를 만듭니다. 같은 네트워크의 컨테이너는 서로 **이름**으로 찾을 수 있어요. `volume` 은 저장 공간을 다루는 말이고, `ls`·`inspect`·`rm` 은 이미 있는 것을 보거나 지울 때 씁니다.', '[0, 2]', 'docker {0} {1} appnet', NULL, '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 7, '같은 네트워크에 두 컨테이너 띄우기', '네트워크 `labnet` 을 만들고, 그 네트워크에 컨테이너 `web` 과 `db` 를 **실행 상태로** 띄우세요. (`alpine`, 명령은 `sleep 3600`)', '`docker network create` 로 만든 뒤, `docker run -d --name 이름 --network labnet alpine sleep 3600` 처럼 붙여요. 확인은 `docker network inspect labnet`.', 'docker network create labnet
docker run -d --name web --network labnet alpine sleep 3600
docker run -d --name db --network labnet alpine sleep 3600
docker network inspect labnet | grep -E ''web|db''

# --network 로 컨테이너를 붙인다. 이름이 주소록처럼 쓰이는 것은 직접 만든 네트워크에서다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; true"]', '["sh", "-c", "( [ \\"$(docker network inspect -f ''{{.Driver}}'' labnet)\\" = bridge ] ) && ( docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw web ) && ( docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw db ) && ( [ \\"$(docker inspect -f ''{{.State.Running}}'' web db | tr -d ''\\\\n'')\\" = truetrue ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "labnet 이 bridge 이다", "cmd": ["sh", "-c", "[ \\"$(docker network inspect -f ''{{.Driver}}'' labnet)\\" = bridge ]"]}, {"label": "web 이 labnet 에 있다", "cmd": ["sh", "-c", "docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw web"]}, {"label": "db 가 labnet 에 있다", "cmd": ["sh", "-c", "docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw db"]}, {"label": "둘 다 실행 중이다", "cmd": ["sh", "-c", "[ \\"$(docker inspect -f ''{{.State.Running}}'' web db | tr -d ''\\\\n'')\\" = truetrue ]"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 8, '이름으로 부르기', '`labnet` 에는 `web` 과 `db` 가 실행 중입니다. **`web` 안에서** `db` 에게 이름으로 ping 을 한 번 보내고, 출력을 `/tmp/ping.txt` 에 저장하세요.', '`docker exec 컨테이너 명령` 으로 컨테이너 안에서 실행해요. ping 은 `-c 1` 이면 한 번만 보냅니다. 주소가 아니라 **이름**을 쓰세요.', 'docker exec web ping -c 1 db > /tmp/ping.txt
cat /tmp/ping.txt

# 직접 만든 네트워크에는 이름 해석(DNS)이 있어 컨테이너 이름이 곧 주소다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker network create labnet >/dev/null 2>&1; docker run -d --name web --network labnet alpine sleep 3600 >/dev/null 2>&1; docker run -d --name db --network labnet alpine sleep 3600 >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q \\"PING db\\" /tmp/ping.txt ) && ( grep -q \\"1 packets received\\" /tmp/ping.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "db 라는 이름으로 보냈다", "cmd": ["sh", "-c", "grep -q \\"PING db\\" /tmp/ping.txt"]}, {"label": "응답이 왔다", "cmd": ["sh", "-c", "grep -q \\"1 packets received\\" /tmp/ping.txt"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 9, '기본 네트워크에 있는 컨테이너 연결하기', '컨테이너 `legacy` 는 기본 네트워크에 있어서 `web` 을 이름으로 찾지 못합니다. **`legacy` 를 `labnet` 에 연결**한 뒤, `legacy` 안에서 `web` 에게 이름으로 ping 을 한 번 보내 출력을 `/tmp/after.txt` 에 저장하세요.', '실행 중인 컨테이너에 네트워크를 더 붙이는 명령은 `docker network connect 네트워크 컨테이너` 예요. 연결 전에 ping 이 실패하는 것도 한 번 보세요.', 'docker exec legacy ping -c 1 -W 1 web
docker network connect labnet legacy
docker exec legacy ping -c 1 web > /tmp/after.txt
cat /tmp/after.txt

# 기본 네트워크에는 이름 해석이 없다. connect 로 직접 만든 네트워크에 붙이면 이름으로 통한다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker network create labnet >/dev/null 2>&1; docker run -d --name web --network labnet alpine sleep 3600 >/dev/null 2>&1; docker run -d --name db --network labnet alpine sleep 3600 >/dev/null 2>&1; docker run -d --name legacy alpine sleep 3600 >/dev/null 2>&1; true"]', '["sh", "-c", "( docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw legacy ) && ( grep -q \\"PING web\\" /tmp/after.txt && grep -q \\"1 packets received\\" /tmp/after.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "legacy 가 labnet 에 있다", "cmd": ["sh", "-c", "docker network inspect -f ''{{range .Containers}}{{.Name}} {{end}}'' labnet | grep -qw legacy"]}, {"label": "web 이름으로 응답이 왔다", "cmd": ["sh", "-c", "grep -q \\"PING web\\" /tmp/after.txt && grep -q \\"1 packets received\\" /tmp/after.txt"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 10, '쓰는 중인 볼륨은 못 지운다', '컨테이너 `holder` 가 볼륨 `keep` 을 쓰며 실행 중입니다. 먼저 `docker volume rm keep` 을 해 보고 **오류 메시지**를 `/tmp/rmerr.txt` 에 저장하세요. 그다음 `holder` 를 정리하고 볼륨 `keep` 을 **삭제**하세요.', '오류는 `2> 파일` 로 받아요. 이 볼륨을 쓰는 컨테이너는 `docker ps -a --filter volume=keep` 으로 찾을 수 있고, 실행 중이면 멈춘 뒤 `rm` 해야 합니다.', 'docker volume rm keep 2> /tmp/rmerr.txt
cat /tmp/rmerr.txt
docker ps -a --filter volume=keep
docker stop holder
docker rm holder
docker volume rm keep

# 컨테이너(멈춘 것도)가 쓰는 볼륨은 지워지지 않는다. 컨테이너를 먼저 지우면 볼륨을 지울 수 있다', '["sh", "-c", "rm -f /tmp/*.txt; rm -rf /tmp/site; docker volume create keep >/dev/null 2>&1; docker run -d --name holder -v keep:/data alpine sleep 3600 >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -qi \\"in use\\" /tmp/rmerr.txt ) && ( ! docker ps -a --format \\"{{.Names}}\\" | grep -qx holder ) && ( ! docker volume inspect keep >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "오류에 in use 가 있다", "cmd": ["sh", "-c", "grep -qi \\"in use\\" /tmp/rmerr.txt"]}, {"label": "holder 컨테이너가 없다", "cmd": ["sh", "-c", "! docker ps -a --format \\"{{.Names}}\\" | grep -qx holder"]}, {"label": "keep 볼륨이 없다", "cmd": ["sh", "-c", "! docker volume inspect keep >/dev/null 2>&1"]}]', '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 228, 11, 'prune 전에 지워질 볼륨 미리 보기', '`docker volume prune` 은 어느 컨테이너도 쓰지 않는 볼륨을 지웁니다. 지우기 **전에** 그 후보(쓰이지 않는 볼륨)만 목록으로 보려면 어느 명령이 알맞을까요?', '`docker volume ls` 에 **조건**을 줄 수 있어요. 아무 컨테이너에도 연결되지 않은 볼륨을 부르는 이름이 있습니다.', NULL, NULL, '[]', 'choice', '["`docker volume ls -f dangling=true`", "`docker volume ls -a`", "`docker volume inspect --unused`", "`docker volume prune --dry-run`"]', 0, '`docker volume ls -f dangling=true` 는 어느 컨테이너에도 연결되지 않은 볼륨만 보여 줍니다. 이 목록이 prune 의 후보와 같은 개념이에요. `volume ls -a` 와 `volume inspect --unused` 는 없는 옵션이고, `volume prune` 에는 미리 보기(`--dry-run`) 옵션이 없어 실행하면 바로 지웁니다.', NULL, NULL, NULL, '[{"title": "Docker 공식 문서: 볼륨", "url": "https://docs.docker.com/engine/storage/volumes/"}, {"title": "Docker 공식 문서: 바인드 마운트", "url": "https://docs.docker.com/engine/storage/bind-mounts/"}, {"title": "Docker 공식 문서: 브리지 네트워크", "url": "https://docs.docker.com/engine/network/drivers/bridge/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 228 AND order_index = 11);

